package com.bank.fx.service;

import java.util.logging.Logger;

// Finds the quote closest to a target rate; ties favour the smaller quote.
public class FxQuoteService {
    private static final Logger log = Logger.getLogger(FxQuoteService.class.getName());

    public int closestQuote(int[] quotes, int target) {
        if (target < quotes[0]) return quotes[0];                 // edge: below all
        if (target > quotes[quotes.length - 1]) return quotes[quotes.length - 1]; // above all
        int start = 0, end = quotes.length - 1;
        while (start <= end) {
            int mid = start + (end - start) / 2;
            if (quotes[mid] == target) {
                log.info(() -> "Exact quote " + target + " available");
                return quotes[mid];
            }
            if (target < quotes[mid]) end = mid - 1; else start = mid + 1;
        }
        // start straddles above, end straddles below the target
        int closest = (quotes[start] - target < target - quotes[end]) ? quotes[start] : quotes[end];
        log.info(() -> "Closest quote to " + target + " is " + closest);
        return closest;
    }
}
